from pathlib import Path
import html,re
root=Path('.')
def esc(s): return html.escape(s,quote=True)
def prompt(folder,n):
 s=(root/folder/'prompts.md').read_text(); m=re.search(r'### '+str(n)+r'\.\n\n(.*?)(?=\n### |\Z)',s,re.S)
 return m.group(1).rstrip('\n')
def quote(s,source): return '<details><summary>Read my exact prompt</summary><pre>'+esc(s)+'</pre><small>'+esc(source)+'</small></details>'
def link(path,label):return '<a href="'+path+'">'+label+' ↗</a>'
mods=[
('01','Origin story','Map the company before diagnosing it.','Dispatch coordinates incidents; Supply manages equipment. Dispatch writes availability and Supply reads it, so a routing change can affect another product without a Supply release.','what is this project about? what is inside the wiki?','01-origin-story/prompts.md · #3','AGENTS.md','Company context','<div class="flow"><b>Incident</b><span>→</span><b>Rank</b><span>→</span><b>Ping</b><span>→</span><b>Assign</b></div><p class="muted">Dispatch → availability record → Supply maintenance planning</p>'),
('02','Super hearing','Make customer evidence navigable.','A CEO research dashboard brings together 147 tickets and four interviews. Quiet workloads and offers moving on are separate symptoms; repeated complaints are not a measure of prevalence.',prompt('02-super-hearing',6),'02-super-hearing/prompts.md · #6','02-super-hearing/ceo-dashboard-source/dist/index.html','Open research dashboard','<div class="stats"><div><strong>147</strong>tickets</div><div><strong>4</strong>interviews</div><div><strong>22</strong>affinity clusters</div></div><p class="muted">Tickets: 29 Jun–7 Sep. Interviews: 2–5 Sep. Fixed research snapshot.</p>'),
('03','Rewind','Turn patterns into an auditable PRD.','The diagnostic dashboard PRD preserves comparable windows and responder-level views. The aggregate decline masks a sharper loss of opportunities for four responders.',prompt('03-rewind',4),'03-rewind/prompts.md · #4','03-rewind/prd-dashboard-dispatch.md','Read diagnostic PRD','<div class="bars"><label>Acceptance · before <b>76.83%</b></label><i style="--w:76.83%"></i><label>Acceptance · after <b>68.45%</b></label><i class="after" style="--w:68.45%"></i></div><p class="muted">398/518 → 332/485 taken. Equal 21-day windows, excluding transition week.</p>'),
('04','X-ray vision','Expose the hidden feedback path.','The technical diagram visualizes the reference code. History loses 0.12 after a decline or miss and gains 0.08 after acceptance. Waiting alone never restores it.',prompt('04-x-ray-vision',5),'04-x-ray-vision/prompts.md · #5','https://miro.com/app/board/uXjVEUy5VSs=/','Open technical diagram board','<div class="flow"><b>Miss / decline<br>−0.12</b><span>→</span><b>History score</b><span>→</span><b>Future rank</b></div><p class="muted">Documented code behavior. A production feedback cycle remains a hypothesis; device and availability functions are stubs.</p>'),
('05','Super speed','Define an experience, not just a number.','The saved brief identifies missing triggers, handler and responder states, recovery rules and acceptance criteria. The prototype below makes a proposed return-to-cover journey clickable.',prompt('05-super-speed',1),'05-super-speed/prompts.md · #1','05-super-speed/brief.md','Read the gap analysis','<div class="flow"><b>Kip reviews</b><span>→</span><b>Mite confirms</b><span>→</span><b>Suitable offer</b></div><p class="muted">This exact saved prompt supports the brief/gap analysis. The prototype build prompt was not preserved in prompts.md; no exact build-prompt claim is made.</p>'),
('06','Sidekicks','Understand the habit we are creating.','The session clarified that a skill defines the review and a schedule runs it. A local Codex skill is not automatically a Miro Sidekick. The actual review-checklist artifact is linked below.',prompt('06-sidekicks',1),'06-sidekicks/prompts.md · #1','.agents/skills/review-checklist/SKILL.md','Read review-checklist','<div class="flow"><b>Skill<br>what to check</b><span>+</span><b>Schedule<br>when to check</b><span>→</span><b>Human review</b></div><p class="muted">The saved prompt produced the explanation. The skill-creation request is preserved in this chat and quoted in the prevention section.</p>')]
sections=''
for num,name,title,body,p,source,path,label,visual in mods:
 sections+=f'<section class="slide module" id="m{num}"><div class="eyebrow">MODULE {num} / {name}</div><h2>{title}</h2><p class="lead">{body}</p><div class="visual">{visual}</div>{link(path,label)}{quote(p,source)}</section>'
prototype=(root/'05-super-speed/prototype.html').read_text()
creation='Class 6&#x20;\n**Make a skill called review-checklist, saved as .agents/skills/review-checklist/SKILL.md inside this project. When I point it at a brief, it checks that the brief: names who owns it, says how we\'ll know it worked, keeps the same scope start to finish, and explains the problem before the fix.**'
